CREATE OR REPLACE FUNCTION public.sync_responsible_columns() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE rec jsonb:=to_jsonb(NEW); BEGIN IF TG_OP='UPDATE' AND public.crm_is_derivation_backfill(to_jsonb(OLD),to_jsonb(NEW)) THEN RETURN NEW; END IF; IF TG_OP='INSERT' AND (rec ? 'assigned_to') AND NEW.assigned_to IS NULL THEN IF rec ? 'owner_id' THEN NEW.assigned_to:=NEW.owner_id; END IF; END IF; IF (rec ? 'assigned_user_id') AND (rec ? 'assigned_to') THEN NEW.assigned_user_id:=NEW.assigned_to; END IF; RETURN NEW; END $$;